<script lang="ts">
  /* eslint-disable svelte/no-at-html-tags -- item icon HTML from snapshot */
  import { facade } from '../bus/gameFacade.js';
  import { dailyLogin } from '../stores/dailyLogin.svelte.ts';
  import { game } from '../../gameManager.ts';
  import { bindQuestRewardTooltipEvents } from '../lib/questRewardTooltips.ts';

  let snap = $derived(dailyLogin.snapshot);
  let rewardsContainerEl: HTMLDivElement | undefined = $state();

  $effect(() => {
    const el = rewardsContainerEl;
    const gm = game;
    if (!el || !gm) return;
    bindQuestRewardTooltipEvents(el, gm);
  });

  function claimReward(e: MouseEvent) {
    e.stopPropagation();
    facade.dispatch({ type: 'CLAIM_DAILY_LOGIN' });
  }

  function closeModal(e: MouseEvent) {
    e.stopPropagation();
    facade.dispatch({ type: 'CLOSE_DAILY_LOGIN_MODAL' });
  }
</script>

<div
  class="stats-content js-modal-content farming-metrics-modal-content daily-login-modal-shell"
  data-action="stopPropagation"
  data-action-stop
>
  <div class="stats-header daily-login-modal-header">
    <h2 id="dailyLoginTitleLabel">{snap.title}</h2>
    <button type="button" class="stats-close" title="Fermer" onclick={closeModal}>&#10005;</button>
  </div>
  <div class="farming-metrics-body daily-login-modal-body" bind:this={rewardsContainerEl}>
    <p class="daily-login-freeze-hint">{snap.freezeHint}</p>
    <div class="daily-login-grid" role="list">
      {#each snap.days as day (day.index)}
        <div
          class="daily-login-day"
          class:daily-login-day--claimed={day.state === 'claimed'}
          class:daily-login-day--current={day.state === 'current'}
          class:daily-login-day--future={day.state === 'future'}
          role="listitem"
        >
          <div class="daily-login-day-header">
            <span class="daily-login-day-label">{day.label}</span>
            {#if day.state === 'claimed'}
              <span class="daily-login-day-status daily-login-day-status--claimed" aria-hidden="true">&#10003;</span>
            {:else if day.state === 'current'}
              <span class="daily-login-day-status daily-login-day-status--current" aria-hidden="true">&#9679;</span>
            {/if}
          </div>
          {#if day.rewards.length > 0}
            <div class="daily-login-day-rewards quest-rewards">
              {#each day.rewards as reward (reward.key)}
                <span
                  class="quest-reward-item"
                  data-tooltip-title={reward.tooltipTitle ?? undefined}
                >
                  {#if reward.img}
                    <img
                      src={reward.img}
                      class={reward.imgClass ?? 'quest-reward-inline-img'}
                      alt=""
                    />
                  {/if}
                  {#if reward.icon}
                    <span class="quest-reward-icon">{@html reward.icon}</span>
                  {/if}
                  {reward.text}
                </span>
              {/each}
            </div>
          {:else}
            <div class="daily-login-day-rewards quest-rewards">—</div>
          {/if}
          {#if day.canClaim}
            <button type="button" class="daily-login-claim-btn" onclick={claimReward}>
              {snap.claimLabel}
            </button>
          {:else if day.state === 'claimed'}
            <span class="daily-login-day-done">{snap.claimedTodayLabel}</span>
          {/if}
        </div>
      {/each}
    </div>
  </div>
</div>
